  var queries = {
  "mysql": "-- Joinscope catalogue query for MySQL 5.7+ and MariaDB 10.2+\n--\n-- Read-only: it reads the database's catalogue (information_schema), never your data.\n-- Run it on the database you want to explore, copy the one cell it returns, and paste\n-- it into Joinscope (Import, \"From a query\"). Both statements are needed: the first lets\n-- the result be longer than 1 KB.\n\nSET SESSION group_concat_max_len = 1073741824;\n\nSELECT CONCAT(\n  '{\"format\":\"joinscope-catalogue\",\"version\":1,\"dialect\":\"mysql\",\"database\":', JSON_QUOTE(DATABASE()),\n  ',\"tables\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('table', t.TABLE_NAME, 'rows', t.TABLE_ROWS, 'comment', t.TABLE_COMMENT, 'engine', t.ENGINE) SEPARATOR ',')\n    FROM information_schema.TABLES t\n    WHERE t.TABLE_SCHEMA = DATABASE() AND t.TABLE_TYPE = 'BASE TABLE'), ''),\n  '],\"columns\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('table', c.TABLE_NAME, 'column', c.COLUMN_NAME, 'position', c.ORDINAL_POSITION,\n      'type', c.COLUMN_TYPE, 'nullable', c.IS_NULLABLE = 'YES', 'default', c.COLUMN_DEFAULT, 'comment', c.COLUMN_COMMENT,\n      'auto', c.EXTRA LIKE '%auto_increment%', 'generated', IFNULL(c.GENERATION_EXPRESSION, '') <> '') SEPARATOR ',')\n    FROM information_schema.COLUMNS c\n    JOIN information_schema.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME AND t.TABLE_TYPE = 'BASE TABLE'\n    WHERE c.TABLE_SCHEMA = DATABASE()), ''),\n  '],\"primary_keys\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('table', k.TABLE_NAME, 'column', k.COLUMN_NAME, 'position', k.ORDINAL_POSITION) SEPARATOR ',')\n    FROM information_schema.KEY_COLUMN_USAGE k\n    WHERE k.TABLE_SCHEMA = DATABASE() AND k.CONSTRAINT_NAME = 'PRIMARY'), ''),\n  '],\"foreign_keys\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('name', k.CONSTRAINT_NAME, 'table', k.TABLE_NAME, 'column', k.COLUMN_NAME, 'position', k.ORDINAL_POSITION,\n      'ref_table', k.REFERENCED_TABLE_NAME, 'ref_column', k.REFERENCED_COLUMN_NAME,\n      'on_delete', (SELECT r.DELETE_RULE FROM information_schema.REFERENTIAL_CONSTRAINTS r\n                    WHERE r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA AND r.TABLE_NAME = k.TABLE_NAME AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME),\n      'on_update', (SELECT r.UPDATE_RULE FROM information_schema.REFERENTIAL_CONSTRAINTS r\n                    WHERE r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA AND r.TABLE_NAME = k.TABLE_NAME AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME)) SEPARATOR ',')\n    FROM information_schema.KEY_COLUMN_USAGE k\n    WHERE k.TABLE_SCHEMA = DATABASE() AND k.REFERENCED_TABLE_NAME IS NOT NULL), ''),\n  '],\"indexes\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('table', s.TABLE_NAME, 'name', s.INDEX_NAME, 'unique', s.NON_UNIQUE = 0, 'type', s.INDEX_TYPE,\n      'column', s.COLUMN_NAME, 'position', s.SEQ_IN_INDEX) SEPARATOR ',')\n    FROM information_schema.STATISTICS s\n    WHERE s.TABLE_SCHEMA = DATABASE() AND s.INDEX_NAME <> 'PRIMARY'), ''),\n  '],\"views\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('name', v.TABLE_NAME, 'sql', v.VIEW_DEFINITION) SEPARATOR ',')\n    FROM information_schema.VIEWS v\n    WHERE v.TABLE_SCHEMA = DATABASE()), ''),\n  '],\"triggers\":[', IFNULL((\n    SELECT GROUP_CONCAT(JSON_OBJECT('name', g.TRIGGER_NAME, 'table', g.EVENT_OBJECT_TABLE, 'timing', g.ACTION_TIMING,\n      'event', g.EVENT_MANIPULATION, 'body', g.ACTION_STATEMENT) SEPARATOR ',')\n    FROM information_schema.TRIGGERS g\n    WHERE g.TRIGGER_SCHEMA = DATABASE()), ''),\n  ']}') AS joinscope;\n",
  "postgres": "-- Joinscope catalogue query for PostgreSQL 12+ (also Supabase and Neon, which run PostgreSQL)\n--\n-- Read-only: it reads the database's catalogue (pg_catalog), never your data.\n-- Run it in the database you want to explore (psql, pgAdmin, DBeaver, or your host's SQL\n-- editor), copy the one cell it returns, and paste it into Joinscope (Import, \"From a query\").\n-- Every schema except PostgreSQL's own is read; tables outside \"public\" keep their schema name.\n-- Partitions are shown as their parent table.\n\nWITH rels AS (\n  SELECT c.oid, n.nspname AS schema, c.relname AS name, c.relkind, c.reltuples,\n         COALESCE(pg_partition_root(c.oid), c.oid) AS root\n  FROM pg_class c\n  JOIN pg_namespace n ON n.oid = c.relnamespace\n  WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname NOT LIKE 'pg_toast%' AND n.nspname NOT LIKE 'pg_temp%'\n),\nroot_names AS (\n  SELECT r.oid, rr.schema, rr.name FROM rels r JOIN rels rr ON rr.oid = r.root\n)\nSELECT json_build_object(\n  'format', 'joinscope-catalogue', 'version', 1, 'dialect', 'postgres', 'database', current_database(),\n  'tables', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name,\n      'rows', (SELECT GREATEST(SUM(GREATEST(p.reltuples, 0)), 0)::bigint FROM rels p WHERE p.root = r.oid AND p.relkind = 'r'),\n      'comment', obj_description(r.oid, 'pg_class')) ORDER BY r.schema, r.name), '[]')\n    FROM rels r WHERE r.relkind IN ('r', 'p') AND r.root = r.oid),\n  'columns', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name, 'column', a.attname, 'position', a.attnum,\n      'type', format_type(a.atttypid, a.atttypmod), 'nullable', NOT a.attnotnull,\n      'default', pg_get_expr(d.adbin, d.adrelid), 'comment', col_description(r.oid, a.attnum),\n      'auto', a.attidentity <> '' OR COALESCE(pg_get_expr(d.adbin, d.adrelid), '') LIKE 'nextval(%',\n      'generated', a.attgenerated <> '') ORDER BY r.schema, r.name, a.attnum), '[]')\n    FROM rels r\n    JOIN pg_attribute a ON a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped\n    LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum\n    WHERE r.relkind IN ('r', 'p') AND r.root = r.oid),\n  'primary_keys', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name, 'column', a.attname, 'position', k.pos)), '[]')\n    FROM pg_constraint con\n    JOIN rels r ON r.oid = con.conrelid AND r.root = r.oid\n    CROSS JOIN LATERAL unnest(con.conkey) WITH ORDINALITY AS k(attnum, pos)\n    JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = k.attnum\n    WHERE con.contype = 'p'),\n  'foreign_keys', (SELECT COALESCE(json_agg(json_build_object(\n      'name', con.conname, 'schema', src.schema, 'table', src.name, 'column', a.attname, 'position', k.pos,\n      'ref_schema', dst.schema, 'ref_table', dst.name, 'ref_column', fa.attname,\n      'on_delete', CASE con.confdeltype WHEN 'c' THEN 'CASCADE' WHEN 'n' THEN 'SET NULL' WHEN 'd' THEN 'SET DEFAULT' WHEN 'r' THEN 'RESTRICT' ELSE 'NO ACTION' END,\n      'on_update', CASE con.confupdtype WHEN 'c' THEN 'CASCADE' WHEN 'n' THEN 'SET NULL' WHEN 'd' THEN 'SET DEFAULT' WHEN 'r' THEN 'RESTRICT' ELSE 'NO ACTION' END)), '[]')\n    FROM pg_constraint con\n    JOIN root_names src ON src.oid = con.conrelid\n    JOIN root_names dst ON dst.oid = con.confrelid\n    CROSS JOIN LATERAL unnest(con.conkey, con.confkey) WITH ORDINALITY AS k(attnum, refnum, pos)\n    JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = k.attnum\n    JOIN pg_attribute fa ON fa.attrelid = con.confrelid AND fa.attnum = k.refnum\n    WHERE con.contype = 'f' AND con.conparentid = 0),\n  'indexes', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name, 'name', ic.relname, 'unique', i.indisunique, 'partial', i.indpred IS NOT NULL,\n      'column', COALESCE(a.attname, pg_get_indexdef(i.indexrelid, k.pos::int, true)), 'position', k.pos)), '[]')\n    FROM pg_index i\n    JOIN rels r ON r.oid = i.indrelid AND r.root = r.oid\n    JOIN pg_class ic ON ic.oid = i.indexrelid\n    CROSS JOIN LATERAL unnest(i.indkey::int2[]) WITH ORDINALITY AS k(attnum, pos)\n    LEFT JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum AND k.attnum > 0\n    WHERE NOT i.indisprimary AND k.pos <= i.indnkeyatts),\n  'views', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'name', r.name, 'sql', pg_get_viewdef(r.oid, true)) ORDER BY r.schema, r.name), '[]')\n    FROM rels r WHERE r.relkind IN ('v', 'm')),\n  'triggers', (SELECT COALESCE(json_agg(json_build_object(\n      'schema', r.schema, 'table', r.name, 'name', t.tgname,\n      'timing', CASE WHEN t.tgtype & 2 <> 0 THEN 'BEFORE' WHEN t.tgtype & 64 <> 0 THEN 'INSTEAD OF' ELSE 'AFTER' END,\n      'event', concat_ws(' OR ', CASE WHEN t.tgtype & 4 <> 0 THEN 'INSERT' END, CASE WHEN t.tgtype & 8 <> 0 THEN 'DELETE' END,\n                         CASE WHEN t.tgtype & 16 <> 0 THEN 'UPDATE' END, CASE WHEN t.tgtype & 32 <> 0 THEN 'TRUNCATE' END),\n      'body', pg_get_triggerdef(t.oid, true))), '[]')\n    FROM pg_trigger t\n    JOIN rels r ON r.oid = t.tgrelid AND r.root = r.oid\n    WHERE NOT t.tgisinternal)\n) AS joinscope;\n",
  "sqlite": "-- Joinscope catalogue query for SQLite 3.38+ (also Cloudflare D1, Turso and other SQLite consoles)\n--\n-- Read-only: it reads the database's own description (sqlite_master and the pragma\n-- functions), never your data. Have the database file? Drop it on Joinscope instead:\n-- it is opened in your browser and nothing is uploaded. Use this query when you only\n-- have a console, then copy the one cell it returns and paste it into Joinscope\n-- (Import, \"From a query\").\n\nSELECT json_object(\n  'format', 'joinscope-catalogue', 'version', 1, 'dialect', 'sqlite',\n  'tables', json((SELECT json_group_array(json_object('table', m.name))\n    FROM sqlite_master m WHERE m.type = 'table' AND m.name NOT LIKE 'sqlite_%')),\n  'columns', json((SELECT json_group_array(json_object(\n      'table', m.name, 'column', p.name, 'position', p.cid + 1, 'type', p.type,\n      'nullable', json(CASE WHEN p.\"notnull\" = 0 AND p.pk = 0 THEN 'true' ELSE 'false' END),\n      'default', p.dflt_value,\n      'auto', json(CASE WHEN p.pk = 1 AND upper(p.type) = 'INTEGER'\n                         AND (SELECT COUNT(*) FROM pragma_table_info(m.name) k WHERE k.pk > 0) = 1 THEN 'true' ELSE 'false' END),\n      'generated', json(CASE WHEN p.hidden IN (2, 3) THEN 'true' ELSE 'false' END)))\n    FROM sqlite_master m, pragma_table_xinfo(m.name) p\n    WHERE m.type = 'table' AND m.name NOT LIKE 'sqlite_%')),\n  'primary_keys', json((SELECT json_group_array(json_object('table', m.name, 'column', p.name, 'position', p.pk))\n    FROM sqlite_master m, pragma_table_info(m.name) p\n    WHERE m.type = 'table' AND p.pk > 0 AND m.name NOT LIKE 'sqlite_%')),\n  'foreign_keys', json((SELECT json_group_array(json_object(\n      'id', f.id, 'table', m.name, 'column', f.\"from\", 'position', f.seq + 1,\n      'ref_table', f.\"table\", 'ref_column', f.\"to\", 'on_delete', f.on_delete, 'on_update', f.on_update))\n    FROM sqlite_master m, pragma_foreign_key_list(m.name) f\n    WHERE m.type = 'table')),\n  'indexes', json((SELECT json_group_array(json_object(\n      'table', m.name, 'name', il.name, 'unique', json(CASE WHEN il.\"unique\" THEN 'true' ELSE 'false' END),\n      'column', ii.name, 'position', ii.seqno + 1))\n    FROM sqlite_master m, pragma_index_list(m.name) il, pragma_index_info(il.name) ii\n    WHERE m.type = 'table' AND il.origin <> 'pk')),\n  'views', json((SELECT json_group_array(json_object('name', name, 'sql', sql))\n    FROM sqlite_master WHERE type = 'view')),\n  'triggers', json((SELECT json_group_array(json_object('name', name, 'table', tbl_name, 'body', sql))\n    FROM sqlite_master WHERE type = 'trigger'))\n) AS joinscope;\n"
};
  if (typeof module !== 'undefined' && module.exports) module.exports = queries;
